--PRODUCTOS (codigo, nombre, marca, modelo, precio, costo, meses de garantia, categoria)


--INVENTARIO INICIAL (todos los productos en la Sucursal Guatemala, 20 unidades, minimo 5)
SELECT S.ID_SUCURSAL, P.ID_PRODUCTO, 20, 5
FROM SUCURSAL S, PRODUCTO P
WHERE S.NOMBRE = 'Sucursal Guatemala';

--CLIENTE CONSUMIDOR FINAL

--EMPLEADOS (todos en Sucursal Guatemala)
SELECT S.ID_SUCURSAL, P.ID_PUESTO, 'Administrador', 'Del Sistema', 8000
FROM SUCURSAL S, PUESTO P WHERE S.NOMBRE = 'Sucursal Guatemala' AND P.NOMBRE = 'Administrador';

SELECT S.ID_SUCURSAL, P.ID_PUESTO, 'Gerente', 'De Prueba', 10000
FROM SUCURSAL S, PUESTO P WHERE S.NOMBRE = 'Sucursal Guatemala' AND P.NOMBRE = 'Gerente';

SELECT S.ID_SUCURSAL, P.ID_PUESTO, 'Vendedor', 'De Prueba', 4500
FROM SUCURSAL S, PUESTO P WHERE S.NOMBRE = 'Sucursal Guatemala' AND P.NOMBRE = 'Vendedor';

SELECT S.ID_SUCURSAL, P.ID_PUESTO, 'Bodeguero', 'De Prueba', 4000
FROM SUCURSAL S, PUESTO P WHERE S.NOMBRE = 'Sucursal Guatemala' AND P.NOMBRE = 'Bodeguero';

--ROLES DE LA APLICACION

--USUARIOS (PASSWORD_HASH temporal, se reemplaza por el hash BCrypt)
SELECT E.ID_EMPLEADO, R.ID_ROL, 'admin', 'CAMBIAR_POR_HASH_BCRYPT'
FROM EMPLEADO E, ROL R WHERE E.NOMBRES = 'Administrador' AND R.NOMBRE = 'ADMINISTRADOR';

SELECT E.ID_EMPLEADO, R.ID_ROL, 'gerente', 'CAMBIAR_POR_HASH_BCRYPT'
FROM EMPLEADO E, ROL R WHERE E.NOMBRES = 'Gerente' AND R.NOMBRE = 'GERENTE';

SELECT E.ID_EMPLEADO, R.ID_ROL, 'vendedor', 'CAMBIAR_POR_HASH_BCRYPT'
FROM EMPLEADO E, ROL R WHERE E.NOMBRES = 'Vendedor' AND R.NOMBRE = 'VENDEDOR';

SELECT E.ID_EMPLEADO, R.ID_ROL, 'bodeguero', 'CAMBIAR_POR_HASH_BCRYPT'
FROM EMPLEADO E, ROL R WHERE E.NOMBRES = 'Bodeguero' AND R.NOMBRE = 'BODEGUERO';

--MENU (opciones principales)

--MENU (pantallas dentro de cada opcion)

--ERMISOS POR ROL (S = si, N = no). Columnas: lectura, escritura, edicion, eliminacion
-- ADMINISTRADOR: todo
SELECT R.ID_ROL, M.ID_MENU, 'S', 'S', 'S', 'S' FROM ROL R, MENU M WHERE R.NOMBRE = 'ADMINISTRADOR';

-- GERENTE: solo lectura en catalogos, movimientos y reportes
SELECT R.ID_ROL, M.ID_MENU, 'S', 'N', 'N', 'N' FROM ROL R, MENU M
WHERE R.NOMBRE = 'GERENTE'
AND (M.NOMBRE_OPCION IN ('Catalogos','Movimientos','Reportes')
  OR M.ID_MENU_PADRE IN (SELECT ID_MENU FROM MENU WHERE NOMBRE_OPCION IN ('Catalogos','Movimientos','Reportes')));

-- VENDEDOR: facturacion, notas de credito, reclamos y clientes (con escritura y edicion)
SELECT R.ID_ROL, M.ID_MENU, 'S', 'S', 'S', 'N' FROM ROL R, MENU M
WHERE R.NOMBRE = 'VENDEDOR'
AND M.NOMBRE_OPCION IN ('Movimientos','Facturacion','Notas de Credito','Reclamos de Garantia','Catalogos','Clientes');

-- VENDEDOR: solo lectura en productos
SELECT R.ID_ROL, M.ID_MENU, 'S', 'N', 'N', 'N' FROM ROL R, MENU M
WHERE R.NOMBRE = 'VENDEDOR' AND M.NOMBRE_OPCION = 'Productos';

-- BODEGUERO: compras e inventario (con escritura y edicion)
SELECT R.ID_ROL, M.ID_MENU, 'S', 'S', 'S', 'N' FROM ROL R, MENU M
WHERE R.NOMBRE = 'BODEGUERO'
AND M.NOMBRE_OPCION IN ('Movimientos','Compras','Inventario','Catalogos','Proveedores');

-- BODEGUERO: solo lectura en productos
SELECT R.ID_ROL, M.ID_MENU, 'S', 'N', 'N', 'N' FROM ROL R, MENU M
WHERE R.NOMBRE = 'BODEGUERO' AND M.NOMBRE_OPCION = 'Productos';

COMMIT;

